    public static function init() {
        add_action('admin_menu', [__CLASS__, 'menu']);
        add_action('admin_enqueue_scripts', [__CLASS__, 'assets']);
        add_action('admin_post_tisa_import_product', [__CLASS__, 'import']);
        add_action('wp_ajax_tisa_search_existing_products', [__CLASS__, 'search_existing_products']);
        add_action('admin_post_tisa_apply_update', [__CLASS__, 'apply_update']);
    }

    /** استایل صفحهٔ خودمان؛ بعد از لایهٔ توکن هاب اگر فعال باشد. */
    public static function assets($hook) {
        if (false === strpos((string) $hook, 'tisa-product-importer')) return;
        $deps = wp_style_is('tisacase-ui', 'registered') ? ['tisacase-ui'] : [];
        wp_enqueue_style('tisa-product-importer', plugins_url('assets/admin.css', __FILE__), $deps, '0.7.0');
    }

    public static function menu() {
        // Put the importer under Products, as the third item from the top.
        add_submenu_page(
            'edit.php?post_type=product', 'افزودن یا شارژ محصول از تلگرام', 'افزودن یا شارژ محصول از تلگرام',
            'manage_woocommerce', 'tisa-product-importer', [__CLASS__, 'page'], 11
        );
    }

    private static function notice() {
        if (empty($_GET['tisa_notice'])) return;
        $type = isset($_GET['tisa_type']) && $_GET['tisa_type'] === 'success' ? 'notice-success' : 'notice-error';
        echo '<div class="notice ' . esc_attr($type) . ' is-dismissible tisa-notice ' . ($type === 'notice-success' ? 'tisa-notice--success' : 'tisa-notice--danger') . '"><p>' . esc_html(wp_unslash($_GET['tisa_notice'])) . '</p></div>';
    }

