    private static function pending_selector($token) {
        $pending = get_transient('tisa_update_' . $token);
        if (!is_array($pending)) { echo '<div class="notice notice-error tisa-notice tisa-notice--danger"><p>اطلاعات شارژ منقضی شده است؛ ZIP را دوباره آپلود کنید.</p></div>'; return; }
        $data = $pending['data'];
        echo '<section class="tisa-card tisa-imp__card tisa-imp__card--wide"><h2 class="tisa-h2">انتخاب محصول برای شارژ</h2><p class="tisa-meta">محصول مناسب را انتخاب کنید. اگر در نتایج نبود، عنوان یا SKU را جستجو کنید.</p>';
        echo '<div class="tisa-imp__search"><input id="tisa-product-search" type="search" class="tisa-input" placeholder="جستجوی عنوان یا SKU…"><button id="tisa-search-btn" type="button" class="tisa-btn tisa-btn--secondary">جستجو</button></div>';
        echo '<div id="tisa-results" class="tisa-imp__results" role="radiogroup" aria-label="نتایج"></div>';
        echo '<div class="tisa-imp__actions"><button id="tisa-apply-update" class="tisa-btn tisa-btn--primary" disabled>اعمال شارژ روی محصول انتخاب‌شده</button><span id="tisa-update-status" class="tisa-meta" aria-live="polite"></span></div></section>';
        $ajax = admin_url('admin-ajax.php');
        $apply = admin_url('admin-post.php');
        $nonce = wp_create_nonce('tisa_update_' . $token);
        echo '<script>(function(){const q=document.getElementById("tisa-product-search"),r=document.getElementById("tisa-results"),b=document.getElementById("tisa-apply-update"),s=document.getElementById("tisa-update-status");let selected=0;q.value=' . wp_json_encode($data['title'] ?? '') . ';function search(){s.textContent="🔎 در حال جستجوی واقعی محصولات...";fetch(' . wp_json_encode($ajax) . '+"?action=tisa_search_existing_products&nonce="+' . wp_json_encode(wp_create_nonce('tisa_search_products')) . '+"&pending="+' . wp_json_encode($token) . '+"&q="+encodeURIComponent(q.value)).then(x=>x.json()).then(j=>{r.innerHTML="";selected=0;b.disabled=true;(j.data||[]).forEach(p=>{const row=document.createElement("label");row.className="tisa-imp__row";row.innerHTML=(p.image?"<img class=\"tisa-imp__thumb\" src=\""+p.image+"\" alt=\"\">":"<span class=\"tisa-imp__thumb tisa-imp__thumb--none\">بدون عکس</span>")+"<span class=\"tisa-imp__row-body\"><span><input type=radio name=tisa_product value="+p.id+"> <strong>"+p.title+"</strong></span><span class=\"tisa-imp__row-meta\"><span>SKU <b class=\"tisa-code\" dir=\"ltr\">"+(p.sku||"-")+"</b></span><span>قیمت فعلی <b class=\"tisa-num\">"+(p.price||"-")+"</b></span><span>ID <b class=\"tisa-code\">"+p.id+"</b></span></span><small class=\"tisa-meta\">ویژگی‌های فعلی: "+((p.attributes||[]).join(" | ")||"-")+"</small></span>";row.querySelector("input").onchange=()=>{selected=p.id;b.disabled=false};r.appendChild(row)});s.textContent=j.data&&j.data.length?"✅ محصول موردنظر را انتخاب کنید.":"محصولی پیدا نشد؛ عبارت دیگری جستجو کنید."}).catch(()=>s.textContent="❌ خطا در جستجو")};document.getElementById("tisa-search-btn").onclick=search;q.onkeydown=e=>{if(e.key==="Enter")search()};if(q.value)search();b.onclick=()=>{if(!selected)return;s.textContent="⚙️ در حال اعمال جایگزینی ویژگی‌ها و تاریخ محصول...";const f=new FormData();f.append("action","tisa_apply_update");f.append("_wpnonce",' . wp_json_encode($nonce) . ');f.append("token",' . wp_json_encode($token) . ');f.append("product_id",selected);fetch(' . wp_json_encode($apply) . ',{method:"POST",body:f}).then(x=>{window.location.href=x.url})}})();</script>';
    }

    private static function fail($message) {
        wp_safe_redirect(add_query_arg(['page'=>'tisa-product-importer','tisa_type'=>'error','tisa_notice'=>rawurlencode($message)], admin_url('admin.php')));
        exit;
    }

    private static function success($message, $product_id = 0) {
        $args = ['page'=>'tisa-product-importer','tisa_type'=>'success','tisa_notice'=>$message];
        if ($product_id) $args['tisa_product_id'] = (int)$product_id;
        wp_safe_redirect(add_query_arg($args, admin_url('admin.php')));
        exit;
    }

    public static function import() {
        if (!current_user_can('manage_woocommerce')) wp_die('دسترسی غیرمجاز');
        check_admin_referer(self::NONCE);
        if (!class_exists('WooCommerce')) self::fail('ووکامرس فعال نیست.');
        if (!class_exists('ZipArchive')) self::fail('افزونه PHP ZipArchive روی هاست فعال نیست. از پشتیبانی هاست بخواهید PHP ZIP را فعال کند.');
        if (empty($_FILES['product_zip']) || $_FILES['product_zip']['error'] !== UPLOAD_ERR_OK) self::fail('فایل ZIP دریافت نشد.');
        $file = $_FILES['product_zip'];
        if (strtolower(pathinfo($file['name'], PATHINFO_EXTENSION)) !== 'zip') self::fail('فقط فایل ZIP مجاز است.');

        $tmp = wp_tempnam('tisa-product');
        if (!move_uploaded_file($file['tmp_name'], $tmp)) self::fail('ذخیره فایل آپلودشده ناموفق بود.');
        $dir = trailingslashit(dirname($tmp)) . 'tisa-' . wp_generate_password(12, false, false);
        wp_mkdir_p($dir);
        $zip = new ZipArchive();
        if ($zip->open($tmp) !== true || !$zip->extractTo($dir)) { @unlink($tmp); self::remove_dir($dir); self::fail('فایل ZIP معتبر نیست یا قابل استخراج نیست.'); }
        @unlink($tmp);

        $json = self::find_file($dir, 'product.json');
        if (!$json) { self::remove_dir($dir); self::fail('product.json داخل ZIP پیدا نشد.'); }
        $data = json_decode(file_get_contents($json), true);
        if (!is_array($data)) { self::remove_dir($dir); self::fail('product.json معتبر نیست.'); }
        $title = sanitize_text_field($data['title'] ?? '');
        $price = (float)($data['price'] ?? 0);
        $prices = is_array($data['prices'] ?? null) ? array_map('floatval', $data['prices']) : [];
        if ($price <= 0 && $prices) $price = (float)reset($prices);
        $prefix = strtoupper(preg_replace('/[^A-Z0-9]/i', '', (string)($data['sku_prefix'] ?? '')));
        $models = self::values($data['models'] ?? []);
        $attrs = is_array($data['attributes'] ?? null) ? $data['attributes'] : [];
        $categories = self::values($data['categories'] ?? []);
        if (($data['mode'] ?? 'new') === 'update') {
            if ($price <= 0 && !$models && !$attrs) { self::remove_dir($dir); self::fail('برای شارژ، حداقل قیمت یا ویژگی جدید لازم است.'); }
            $token = wp_generate_password(20, false, false);
            set_transient('tisa_update_' . $token, ['data'=>$data, 'dir'=>$dir], HOUR_IN_SECONDS);
            wp_safe_redirect(add_query_arg(['page'=>'tisa-product-importer', 'tisa_pending'=>$token], admin_url('admin.php')));
            exit;
        }

        if (!$title || $price <= 0 || !$prefix || !$models) { self::remove_dir($dir); self::fail('عنوان، قیمت، پیشوند SKU یا مدل‌ها ناقص است.'); }
        $attrs = self::clean_attributes($attrs, $models);
        // A one-value model is not a selectable attribute. It belongs in the
        // product data/title, while two or more values create a variation axis.
        if (count($models) >= 2) {
            // Model must always be the first attribute shown in WooCommerce.
            $attrs = array_merge(['مدل' => $models], $attrs);
        }
        $is_variable = !empty($attrs);
        $sku = self::next_sku($prefix);
        $product_id = wp_insert_post([
            'post_title' => $title,
            'post_content' => '',
            'post_status' => 'draft',
            'post_type' => 'product',
            'post_author' => get_current_user_id(),
        ], true);
        if (is_wp_error($product_id)) { self::remove_dir($dir); self::fail($product_id->get_error_message()); }

        try {
            wp_set_object_terms($product_id, $is_variable ? 'variable' : 'simple', 'product_type');
            update_post_meta($product_id, '_sku', $sku);
            update_post_meta($product_id, '_visibility', 'visible');
            update_post_meta($product_id, '_stock_status', 'instock');
            update_post_meta($product_id, '_price', $price);
            update_post_meta($product_id, '_regular_price', $price);
            if ($is_variable) self::set_attributes($product_id, $attrs);
            self::set_categories($product_id, $categories);
            self::attach_images($product_id, $dir);
            if ($is_variable) self::make_variations($product_id, $attrs, $price, $prices);
            self::remove_dir($dir);
            self::success('محصول با موفقیت ساخته شد.', $product_id);
        } catch (Throwable $e) {
            error_log('[Tisa Product Importer] ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
            wp_delete_post($product_id, true);
            self::remove_dir($dir);
            self::fail('ساخت محصول ناموفق بود: ' . $e->getMessage());
        }
    }

    public static function search_existing_products() {
        if (!current_user_can('manage_woocommerce') || !wp_verify_nonce($_GET['nonce'] ?? '', 'tisa_search_products')) wp_send_json_error('دسترسی غیرمجاز', 403);
        $q = sanitize_text_field(wp_unslash($_GET['q'] ?? ''));
        $args = ['post_type'=>'product', 'post_status'=>['publish','draft','pending','private'], 'posts_per_page'=>30, 's'=> $q, 'orderby'=>'relevance'];
        $query = new WP_Query($args);
        $items = [];
        foreach ($query->posts as $post) {
            $items[] = self::candidate_data($post->ID);
        }
        if ($q !== '') {
            global $wpdb;
            $ids = $wpdb->get_col($wpdb->prepare("SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key='_sku' AND meta_value LIKE %s LIMIT 30", '%' . $wpdb->esc_like($q) . '%'));
            foreach ($ids as $id) { $post=get_post($id); if ($post && $post->post_type==='product') $items[] = self::candidate_data($post->ID); }
        }
        $unique=[]; foreach ($items as $item) $unique[$item['id']]=$item;
        wp_send_json_success(array_values($unique));
    }

    private static function candidate_data($product_id) {
        $product = function_exists('wc_get_product') ? wc_get_product($product_id) : null;
        $attributes = [];
        if ($product) foreach ($product->get_attributes() as $attribute) $attributes[] = $attribute->get_name() . ': ' . implode(' | ', $attribute->get_options());
        return ['id'=>$product_id, 'title'=>get_the_title($product_id), 'sku'=>(string)get_post_meta($product_id, '_sku', true), 'price'=>$product ? $product->get_price() : '', 'attributes'=>$attributes, 'image'=>get_the_post_thumbnail_url($product_id, 'thumbnail') ?: ''];
    }

    public static function apply_update() {
        if (!current_user_can('manage_woocommerce')) wp_die('دسترسی غیرمجاز');
        $token = sanitize_text_field(wp_unslash($_POST['token'] ?? ''));
        check_admin_referer('tisa_update_' . $token);
        $pending = get_transient('tisa_update_' . $token);
        $product_id = absint($_POST['product_id'] ?? 0);
        if (!is_array($pending) || !$product_id || get_post_type($product_id) !== 'product') self::fail('اطلاعات شارژ یا محصول انتخاب‌شده معتبر نیست.');
        try {
            self::update_existing_product($product_id, $pending['data'], $pending['dir']);
            delete_transient('tisa_update_' . $token);
            self::remove_dir($pending['dir']);
            self::success('شارژ محصول با موفقیت انجام شد.', $product_id);
        } catch (Throwable $e) {
            error_log('[Tisa Product Importer update] ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
            self::remove_dir($pending['dir']);
            self::fail('شارژ محصول ناموفق بود: ' . $e->getMessage());
        }
    }

    private static function update_existing_product($product_id, $data, $dir) {
        $price = (float)($data['price'] ?? 0);
        $prices = is_array($data['prices'] ?? null) ? array_map('floatval', $data['prices']) : [];
        if ($price <= 0 && $prices) $price = (float)reset($prices);
        $models = self::values($data['models'] ?? []);
        $incoming_attrs = is_array($data['attributes'] ?? null) ? $data['attributes'] : [];
        $has_variation_update = !empty($models) || !empty($incoming_attrs) || !empty($prices);
        if ($price <= 0 && !$has_variation_update) throw new Exception('هیچ قیمت یا ویژگی جدیدی برای اعمال ارسال نشده است.');
        // No price in the restock ZIP means the current product price is
        // authoritative. Only overwrite it when a new price was supplied.
        $effective_price = $price > 0 ? $price : (float)get_post_meta($product_id, '_regular_price', true);
        if ($effective_price <= 0) {
            $live_variations = get_children(['post_parent'=>$product_id, 'post_type'=>'product_variation', 'post_status'=>'publish', 'fields'=>'ids']);
            if ($live_variations) $effective_price = (float)get_post_meta(reset($live_variations), '_regular_price', true);
        }
        if ($price > 0) {
            update_post_meta($product_id, '_regular_price', $price);
            update_post_meta($product_id, '_price', $price);
        }
        if ($has_variation_update) {
            $attrs = self::clean_attributes($incoming_attrs, $models);
            // Omitted fields mean "leave unchanged". Supplied fields replace
            // their old values, while the model axis is replaced only when
            // new models were actually included in the ZIP.
            $existing_attrs = [];
            $existing = get_post_meta($product_id, '_product_attributes', true);
            if (is_array($existing)) {
                foreach ($existing as $attribute) {
                    $name = (string)($attribute['name'] ?? '');
                    $values = self::values(preg_split('/\s*\|\s*/u', (string)($attribute['value'] ?? '')));
                    if ($name && count($values) >= 2) $existing_attrs[$name] = $values;
                }
            }
            if ($models) {
                // The incoming model list is authoritative. Remove the old
                // model axis before rebuilding it; otherwise array_merge
                // would let the existing مدل overwrite the new list.
                foreach (array_keys($existing_attrs) as $existing_name) {
                    if (in_array(mb_strtolower(trim($existing_name)), ['مدل', 'model'], true)) unset($existing_attrs[$existing_name]);
                }
                $attrs = array_merge(['مدل'=>$models], $existing_attrs, $attrs);
            } else {
                $attrs = array_merge($existing_attrs, $attrs);
            }
            $is_variable = !empty($attrs);
            wp_set_object_terms($product_id, $is_variable ? 'variable' : 'simple', 'product_type');
            if ($is_variable) {
                self::set_attributes($product_id, $attrs);
                if ($effective_price <= 0) throw new Exception('قیمت فعلی محصول پیدا نشد.');
                self::replace_variations($product_id, $attrs, $effective_price, $prices);
            } else {
                delete_post_meta($product_id, '_product_attributes');
                foreach (get_children(['post_parent'=>$product_id,'post_type'=>'product_variation','post_status'=>'any','fields'=>'ids']) as $old) { wp_update_post(['ID'=>$old,'post_status'=>'private']); update_post_meta($old,'_stock_status','outofstock'); }
            }
        } elseif ($price > 0) {
            // Price-only restock: keep the existing attribute matrix and update
            // every live variation price without rebuilding combinations.
            foreach (get_children(['post_parent'=>$product_id,'post_type'=>'product_variation','post_status'=>'publish','fields'=>'ids']) as $variation_id) {
                update_post_meta($variation_id, '_regular_price', $price);
                update_post_meta($variation_id, '_price', $price);
            }
        }
        if (($data['image_mode'] ?? 'keep') === 'replace') self::attach_images($product_id, $dir);
        $now = current_time('mysql');
        wp_update_post(['ID'=>$product_id, 'post_date'=>$now, 'post_date_gmt'=>get_gmt_from_date($now), 'post_modified'=>$now, 'post_modified_gmt'=>get_gmt_from_date($now)]);
        if (function_exists('wc_delete_product_transients')) wc_delete_product_transients($product_id);
    }

    private static function replace_variations($product_id, $attrs, $price, $prices = []) {
        // Restock is an authoritative replacement: remove every old
        // variation, including private ones, before generating the new
        // cartesian matrix. The parent product and its order history remain.
        foreach (get_children(['post_parent'=>$product_id,'post_type'=>'product_variation','post_status'=>'any','fields'=>'ids']) as $old) {
            wp_delete_post($old, true);
        }
        self::make_variations($product_id, $attrs, $price, $prices);
    }

    private static function values($value) {
        if (!is_array($value)) return [];
        $out = [];
        foreach ($value as $v) { $v = sanitize_text_field((string)$v); if ($v !== '' && !in_array($v, $out, true)) $out[] = $v; }
        return $out;
    }

    private static function clean_attributes($attrs, $models) {
        $out = [];
        foreach ($attrs as $name => $values) {
            $name = sanitize_text_field((string)$name);
            if (!$name || in_array(mb_strtolower($name), ['مدل','model'], true) || !is_array($values)) continue;
            $values = self::values($values);
            // One value gives the customer nothing to choose, so it is part
            // of the product identity rather than a WooCommerce attribute.
            if (count($values) >= 2) $out[$name] = $values;
        }
        return $out;
    }

    private static function next_sku($prefix) {
        global $wpdb;
        $like = $wpdb->esc_like($prefix) . '%';
        $rows = $wpdb->get_col($wpdb->prepare("SELECT meta_value FROM {$wpdb->postmeta} WHERE meta_key='_sku' AND meta_value LIKE %s", $like));
        $max = 0;
        foreach ($rows as $sku) {
            if (preg_match('/^' . preg_quote($prefix, '/') . '(\d+)$/i', (string)$sku, $m)) $max = max($max, (int)$m[1]);
        }
        return $prefix . ($max + 1);
    }

    private static function set_attributes($product_id, $attrs) {
        $meta = [];
        foreach ($attrs as $name => $values) {
            $slug = sanitize_title($name);
            $meta[$slug] = ['name'=>$name, 'value'=>implode(' | ', $values), 'position'=>count($meta), 'is_visible'=>1, 'is_variation'=>1, 'is_taxonomy'=>0];
        }
        update_post_meta($product_id, '_product_attributes', $meta);
    }

    private static function set_categories($product_id, $categories) {
        $ids = [];
        foreach ($categories as $path) {
            if (in_array(trim($path), ['فروش ویژه','💥 بلک فرایدی','محصولات عمده'], true)) continue;
            $parts = preg_split('/\s*(?:>|\/|»|→)\s*/u', trim($path));
            $parts = self::complete_category_path($parts);
            $parent = 0; $last = 0;
            foreach ($parts as $part) {
                $part = trim($part); if ($part === '') continue;
                $term = get_terms(['taxonomy'=>'product_cat','name'=>$part,'parent'=>$parent,'hide_empty'=>false,'number'=>1]);
                if (!empty($term) && !is_wp_error($term)) $last = (int)$term[0]->term_id;
                else { $created = wp_insert_term($part, 'product_cat', ['parent'=>$parent]); if (is_wp_error($created)) continue; $last = (int)$created['term_id']; }
                // WooCommerce/WordPress does not automatically assign every
                // ancestor when a child is assigned. Keep the complete path:
                // parent first, then child, exactly as selected in the editor.
                $ids[] = $last;
                $parent = $last;
            }

        }
        if ($ids) wp_set_object_terms($product_id, array_unique($ids), 'product_cat', false);
    }

    private static function complete_category_path($parts) {
        $parts = array_values(array_filter(array_map('trim', (array)$parts)));
        if (count($parts) !== 1) return $parts;
        $chain = [$parts[0]]; $current = $parts[0]; $guard = 0;
        while (isset(self::CATEGORY_PARENTS[$current]) && $guard++ < 10) {
            $current = self::CATEGORY_PARENTS[$current];
            array_unshift($chain, $current);
        }
        return $chain;
    }

    private static function price_for_combo($combo, $default, $prices) {
        if (!$prices || empty($combo)) return $default;
        foreach ($combo as $name => $value) {
            if (mb_strtolower(trim($name)) !== 'مدل' && mb_strtolower(trim($name)) !== 'model') continue;
            $model = mb_strtolower((string)$value);
            $group = preg_match('/\\biphone\\b/i', $model) ? 'iphone' : 'android';
            if (!empty($prices[$group])) return (float)$prices[$group];
        }
        return $default;
    }

    private static function make_variations($product_id, $attrs, $price, $prices = []) {
        $combos = [[]];
        foreach ($attrs as $name => $values) {
            $next = [];
            foreach ($combos as $combo) foreach ($values as $value) {
                $copy = $combo; $copy[$name] = $value; $next[] = $copy;
            }
            $combos = $next;
        }
        foreach ($combos as $combo) {
            $variation_price = self::price_for_combo($combo, $price, $prices);
            // Use WooCommerce's CRUD layer rather than raw post meta. This
            // writes the exact attribute keys/values used by the variation
            // dropdowns in the product editor.
            $variation = new WC_Product_Variation();
            $variation->set_parent_id($product_id);
            $variation->set_status('publish');
            $variation->set_regular_price((string)$variation_price);
            $variation->set_price((string)$variation_price);
            $variation->set_manage_stock(false);
            $variation->set_stock_status('instock');
            $variation_attributes = [];
            foreach ($combo as $name => $value) {
                $variation_attributes[sanitize_title($name)] = sanitize_title($value);
            }
            $variation->set_attributes($variation_attributes);
            $variation_id = $variation->save();
            // Write the exact admin-editor meta explicitly as well. This
            // guarantees WooCommerce can preselect custom (non-taxonomy)
            // attribute values instead of showing «هر مدل» / «هر رنگ».
            foreach ($combo as $name => $value) {
                update_post_meta($variation_id, 'attribute_' . sanitize_title($name), sanitize_title($value));
            }
            clean_post_cache($variation_id);
        }
        if (class_exists('WC_Product_Variable')) WC_Product_Variable::sync($product_id);
        if (function_exists('wc_delete_product_transients')) wc_delete_product_transients($product_id);
    }

    private static function attach_images($product_id, $dir) {
        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $files = glob(trailingslashit($dir) . '**/*.{jpg,jpeg,png,webp}', GLOB_BRACE);
        if (!$files) $files = self::recursive_images($dir);
        $ids = [];
        foreach ($files as $file) {
            $upload = wp_upload_bits(basename($file), null, file_get_contents($file));
            if (!empty($upload['error'])) continue;
            $type = wp_check_filetype($upload['file']);
            $attachment = ['post_mime_type'=>$type['type'], 'post_title'=>sanitize_file_name(pathinfo($file, PATHINFO_FILENAME)), 'post_status'=>'inherit'];
            $id = wp_insert_attachment($attachment, $upload['file'], $product_id);
            if (!$id) continue;
            wp_update_attachment_metadata($id, wp_generate_attachment_metadata($id, $upload['file']));
            $ids[] = $id;
        }
        if ($ids) { set_post_thumbnail($product_id, $ids[0]); update_post_meta($product_id, '_product_image_gallery', implode(',', array_slice($ids, 1))); }
    }

    private static function recursive_images($dir) {
        $out = []; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
        foreach ($it as $f) if (preg_match('/\.(jpe?g|png|webp)$/i', $f->getFilename())) $out[] = $f->getPathname();
        return $out;
    }

    private static function find_file($dir, $name) {
        $files = glob(trailingslashit($dir) . '**/' . $name, GLOB_BRACE); return $files[0] ?? (file_exists($dir.'/'.$name) ? $dir.'/'.$name : false);
    }

    private static function remove_dir($dir) {
        if (!is_dir($dir)) return; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
        foreach ($it as $f) $f->isDir() ? @rmdir($f->getPathname()) : @unlink($f->getPathname()); @rmdir($dir);
    }
}
Tisa_Product_Zip_Importer::init();
